import re, datetime as dt, hashlib

def parse(path):
    txt = open(path).read()
    out = []
    for blk in re.findall(r'BEGIN:VEVENT(.*?)END:VEVENT', txt, re.S):
        s = re.search(r'DTSTART[^:]*:(\S+)', blk).group(1)
        e = re.search(r'DTEND[^:]*:(\S+)', blk).group(1)
        f = lambda x: dt.datetime.strptime(x, '%Y%m%dT%H%M%SZ')
        out.append((f(s), f(e)))
    return out

cal = {n: parse('/app/%s_calendar.ics' % n) for n in ('alice','bob','carol')}

def allowed(name, day):
    T = lambda h, m=0: day.replace(hour=h, minute=m, second=0, microsecond=0)
    if name == 'alice':
        return [(T(9), T(14))]
    if name == 'bob':
        end = T(16,30) if day.weekday() in (1,3) else T(18)
        return [(T(10), end)]
    if name == 'carol':
        return [(T(9), T(12)), (T(12,30), T(17))]

def free(name, s, e):
    if not any(s >= a and e <= b for a, b in allowed(name, s)):
        return False
    return all(not (s < b and a < e) for a, b in cal[name])

def carol_buffer_ok(s, e):
    for a, b in cal['carol']:
        if b.hour*60 + b.minute >= 16*60 + 45:
            if b <= s < b + dt.timedelta(minutes=15):
                return False
    return True

start = dt.datetime(2024,1,15,9,0)
valid = []
for i in range(5):
    day = start + dt.timedelta(days=i)
    s = day
    limit = day.replace(hour=18)
    while s + dt.timedelta(minutes=60) <= limit:
        e = s + dt.timedelta(minutes=60)
        if all(free(n, s, e) for n in cal) and carol_buffer_ok(s, e):
            valid.append((s, e))
        s += dt.timedelta(minutes=1)

per_day = {}
for s, e in valid:
    per_day[str(s.date())] = per_day.get(str(s.date()), 0) + 1
print('total valid slots:', len(valid))
